    from jsonb_populate_recordset(null::public.questions, $catalog_json$[{"id":"33066229-071c-4cb8-81e7-2748fe883608","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"If 3x + 8 = 56, what is x?","options":["16","14","18","20"],"position":0,"type":"multiple_choice","config":{"sat_topic":"Algebra"},"points":1,"required":true,"group_name":"Linear equations"},{"id":"5a66c3c1-f938-4a7e-a546-51fbfee51792","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"A price of $90 is reduced by 20%. What is the new price in dollars?","options":["70","74","76","72"],"position":1,"type":"multiple_choice","config":{"sat_topic":"Problem-Solving and Data Analysis"},"points":1,"required":true,"group_name":"Percentages"},{"id":"0f542746-21d0-4e46-8fce-fc387e07facb","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"What is the positive solution of x² = 100?","options":[],"position":2,"type":"numeric_answer","config":{"sat_topic":"Advanced Math"},"points":1,"required":true,"group_name":"Quadratic equations"},{"id":"282e8849-7be5-46cb-a0b3-1b1330adaa4f","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"A line passes through (1, 11) and (5, 23). What is its slope?","options":["7","3","1","5"],"position":3,"type":"multiple_choice","config":{"sat_topic":"Algebra"},"points":1,"required":true,"group_name":"Slope"},{"id":"b6e32e4e-ca86-4736-ab0c-cf134b51d479","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"A rectangle has width 12 and length 16. What is its area?","options":["192","190","194","196"],"position":4,"type":"multiple_choice","config":{"sat_topic":"Geometry and Trigonometry"},"points":1,"required":true,"group_name":"Area"},{"id":"1371e192-7c53-495a-9391-4e67a5e75371","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"What is the arithmetic mean of 13, 17, 21, and 25?","options":["17","21","23","19"],"position":5,"type":"multiple_choice","config":{"sat_topic":"Problem-Solving and Data Analysis"},"points":1,"required":true,"group_name":"Mean"},{"id":"94539c72-52f0-4092-b663-573f15eb5312","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"A bag contains 14 red and 42 blue marbles. If one marble is selected at random, what percent chance is it red?","options":["27","29","25","23"],"position":6,"type":"multiple_choice","config":{"sat_topic":"Problem-Solving and Data Analysis"},"points":1,"required":true,"group_name":"Probability"},{"id":"b5052ab6-5967-4f3f-bae8-aecf39fdacc0","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"The function f(x) = 2x² − 15. What is f(3)?","options":[],"position":7,"type":"numeric_answer","config":{"sat_topic":"Advanced Math"},"points":1,"required":true,"group_name":"Quadratic functions"},{"id":"09c9bf39-cf63-40e6-991d-651ae4265383","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"The number of cells starts at 16 and triples every hour. How many are there after 3 hours?","options":["432","430","434","436"],"position":8,"type":"multiple_choice","config":{"sat_topic":"Advanced Math"},"points":1,"required":true,"group_name":"Exponential growth"},{"id":"0fb4c3ea-312d-4b8f-8c87-53fddd4614ff","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"In a right triangle, the legs are 51 and 68. What is the hypotenuse?","options":["83","87","89","85"],"position":9,"type":"multiple_choice","config":{"sat_topic":"Geometry and Trigonometry"},"points":1,"required":true,"group_name":"Right triangles"},{"id":"ead1e0c5-8a82-4f20-957e-3d8044ab8058","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"If 2x + y = 90 and x − y = 18, what is x?","options":["38","40","36","34"],"position":10,"type":"multiple_choice","config":{"sat_topic":"Algebra"},"points":1,"required":true,"group_name":"Systems of equations"},{"id":"17d6c8e1-dbe5-41b5-8e6f-f9813da5b01b","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"If 3x + 19 = 133, what is x?","options":["42","38","36","40"],"position":11,"type":"multiple_choice","config":{"sat_topic":"Algebra"},"points":1,"