 and Data Analysis"},"points":1,"required":true,"group_name":"Probability"},{"id":"4d03fdc0-3ee5-4a69-92cc-43e69d30fa90","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"The function f(x) = 2x² − 26. What is f(3)?","options":["-6","-4","-8","-10"],"position":18,"type":"multiple_choice","config":{"sat_topic":"Advanced Math"},"points":1,"required":true,"group_name":"Quadratic functions"},{"id":"57793462-c345-41fd-836e-0739d078e697","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"The number of cells starts at 27 and triples every hour. How many are there after 3 hours?","options":["733","729","727","731"],"position":19,"type":"multiple_choice","config":{"sat_topic":"Advanced Math"},"points":1,"required":true,"group_name":"Exponential growth"},{"id":"2d18123c-e370-4a63-9090-23f83e160c50","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"In a right triangle, the legs are 84 and 112. What is the hypotenuse?","options":["140","138","142","144"],"position":20,"type":"multiple_choice","config":{"sat_topic":"Geometry and Trigonometry"},"points":1,"required":true,"group_name":"Right triangles"},{"id":"9e5b4a4c-ab6a-4299-a05d-2da285cdabfd","test_id":"2b07157d-ac83-5713-9ee9-ea7e0329dc2d","prompt":"If 2x + y = 145 and x − y = 29, what is x?","options":[],"position":21,"type":"numeric_answer","config":{"sat_topic":"Algebra"},"points":1,"required":true,"group_name":"Systems of equations"},{"id":"d03cf6d3-33ff-4a8f-9ac9-bbbf434c78e1","test_id":"70767467-ea94-5677-9212-77a335806796","prompt":"Passage A · The study started in 2019.","options":["True","False","Not Given"],"position":0,"type":"true_false_not_given","config":{},"points":1,"required":true,"group_name":""},{"id":"86fa80dc-ca4e-4bcc-8506-bf585fe0cfed","test_id":"70767467-ea94-5677-9212-77a335806796","prompt":"Passage A · All streets in the study had the same amount of tree cover.","options":["True","False","Not Given"],"position":1,"type":"true_false_not_given","config":{},"points":1,"required