50d88030-90f2-471d-a21e-bccbd356ff81","answer":"However","accepted":"However","explanation":"","evidence":""},{"question_id":"d8d9d8b8-7578-4c36-93da-79c1e9e4e702","answer":"By contrast","accepted":"By contrast","explanation":"","evidence":""},{"question_id":"7c080486-8847-488c-bd6e-7a1c33fa237f","answer":"As a result","accepted":"As a result","explanation":"","evidence":""},{"question_id":"94aea736-9d3f-4d15-a8ca-e7201f2bd323","answer":"It captured particles the first filter missed.","accepted":"It captured particles the first filter missed.","explanation":"","evidence":"A filter removed most large particles but allowed smaller particles to pass. A second filter caught most of those smaller particles."},{"question_id":"0d11cac1-8609-428f-a0bb-eb352f058ac1","answer":"Service frequency changed at the same time.","accepted":"Service frequency changed at the same time.","explanation":"","evidence":"A city reduced its bus fares while increasing the frequency of service. Ridership increased over the next quarter."},{"question_id":"ccf123f7-493f-4035-954a-578db048f326","answer":"Artists can choose the same materials for different reasons.","accepted":"Artists can choose the same materials for different reasons.","explanation":"","evidence":"Some artists in the exhibition use discarded materials to reduce waste. Others choose those materials because their irregular shapes invite experimentation."},{"question_id":"ac8388ef-e523-4e5d-b96f-786abf79b14f","answer":"Rain may have affected the instrument.","accepted":"Rain may have affected the instrument.","explanation":"","evidence":"The first night’s measurements were discarded because the instrument had been exposed to rain. Later measurements were taken under a protective cover."},{"question_id":"1d1ac4ff-33f3-42e6-b556-4483bb7bb0af","answer":"A funded upgrade to a tram stop.","accepted":"A funded upgrade to a tram stop.","explanation":"","evidence":"A local newspaper published a weekly column about transit improvements. Its writers focused on proposals that had been funded and excluded proposals still under debate."},{"question_id":"fb7b9711-43ef-4537-9b94-ffc8ce7db7ed","answer":"One damaged pipe accounted for most of the loss.","accepted":"One damaged pipe accounted for most of the loss.","explanation":"","evidence":"The village installed meters on all public taps. Officials later found that most of the water loss came from a single damaged pipe."},{"question_id":"1fbe123c-9112-4fa1-92ba-bd91417f804d","answer":"Simple design does not guarantee easy repair.","accepted":"Simple design does not guarantee easy repair.","explanation":"","evidence":"The author describes the machine first as surprisingly simple and later as difficult to repair without specialized tools."},{"question_id":"e766f48d-4726-4f07-8be7-f177f79f22b2","answer":"How the coating affects roof temperatures at night.","accepted":"How the coating affects roof temperatures at night.","explanation":"","evidence":"In a field trial, a reflective coating lowered roof temperatures during sunny afternoons. The study recorded no readings after dark."},{"question_id":"cbcd13ef-76b2-4f5d-9b5d-c30dad7f3a77","answer":"Increasing the diversity of street trees.","accepted":"Increasing the diversity of street trees.","explanation":"","evidence":"A tree inventory revealed that just two species accounted for most trees on a single street. The city plans to plant more species there."},{"question_id":"71ebab70-eb55-45d7-bcd6-9999e9c9c0e5","answer":"functional","accepted":"functional","explanation":"","evidence":""},{"question_id":"ec8becfb-366e-46e7-a937-e08d1a366a65","answer":"confirmed","accepted":"confirmed","explanation":"","evidence":""},{"question_id":"a33647bf-b5f7-41b8-9840-e6bfda05ed90","answer":"rare","accepted":"rare","explanation":"","evidence":""},{"question_id":"014533ee-50f4-46d2-bbf0-2faf608b89ca","answer":"reduced","accepted":"reduced","explanation":"","evidence":""},{"question_id":"3355d3a0-1355-44fd-b740-6ac4c9a0e924","answer":"kept","accepted":"kept","explanation":"","evidence":""},{"question_id":"a27e6b2f-fe81-42d3-ad18-50a3bd249273","answer":"brief","accepted":"brief","explanation":"","evidence":""},{"question_id":"26e418de-f78a-4079-986d-5a223a398751","answer":"initial","accepted":"initial","explanation":"","evidence":""},{"question_id":"d8cc8d86-88c3-4447-825f-094cc6b1eb2b","answer":"assigned","accepted":"assigned","explanation":"","evidence":""},{"question_id":"f9404715-ce8f-4620-b1a0-77a3be28871e","answer":"able to recover","accepted":"able to recover","explanation":"","evidence":""},{"question_id":"d4657394-373a-4993-a2a4-d16633b529fc","answer":"addresses","accepted":"addresses","explanation":"","evidence":""},{"question_id":"a98d299d-8042-40ae-ba23-6c7705c6d893","answer":"had calibrated","accepted":"had calibrated","explanation":"","evidence":""},{"question_id":"0c634baa-f68b-4e65-bf4e-68d3d6ab2a34","answer":"date","accepted":"date","explanation":"","evidence":""},{"question_id":"721e52c9-8ec2-42d0-a392-116af6e71192","answer":"is","accepted":"is","explanation":"","evidence":""},{"question_id":"56361ec5-d758-4f0b-9741-f18795568d0e","answer":"would have completed","accepted":"would have completed","explanation":"","evidence":""},{"question_id":"d9d1e960-f464-4dfc-ae2e-1f918f62566e","answer":"placing","accepted":"placing","explanation":"","evidence":""},{"question_id":"e9fddaa8-45bb-402b-b310-8f259a22e728","answer":"support","accepted":"support","explanation":"","evidence":""},{"question_id":"cc543d92-5410-441e-9b5a-05c6f292b321","answer":"was","accepted":"was","explanation":"","evidence":""},{"question_id":"751caebe-642b-4e42-810a-30cc901803e5","answer":"whom","accepted":"whom","explanation":"","evidence":""},{"question_id":"0fb23c38-bb1f-4720-8924-8dde9a4ebdeb","answer":"An increase in midday visits.","accepted":"An increase in midday visits.","explanation":"","evidence":"After adding shaded benches, a park saw more visitors between noon and two. Morning visits remained unchanged."},{"question_id":"4b5ef1c8-27be-43fa-a1c5-08ca89fe1fec","answer":"Writing summaries was associated with better recall.","accepted":"Writing summaries was associated with better recall.","explanation":"","evidence":"Two groups read the same article. The group that wrote summaries remembered more details the following week."},{"question_id":"1f98bf4c-fbfc-4828-a281-ff5045958f76","answer":"Temperature.","accepted":"Temperature.","explanation":"","evidence":"Most of the seeds germinated at 20°C, but few germinated at 5°C. The other conditions were identical."},{"question_id":"fec99d89-dc1b-49ba-9e6d-c4bf69c4145f","answer":"Higher purchase costs versus lower expected maintenance costs.","accepted":"Higher purchase costs versus lower expected maintenance costs.","explanation":"","evidence":"Although electric buses cost more initially, the district expects lower maintenance bills over the next decade."},{"question_id":"c8f48bea-be8f-4f1b-9992-1ace6520e258","answer":"Outdoor conditions were outside the study.","accepted":"Outdoor conditions were outside the study.","explanation":"","evidence":"The study included only plants grown indoors. The researchers caution that wind and pests could change the results outdoors."},{"question_id":"8b498489-5bc1-406f-8ae5-6c5fe83320fc","answer":"Why attendance increased.","accepted":"Why attendance increased.","explanation":"","evidence":"A museum moved its free evening from Tuesday to Friday. In the next month, evening attendance rose, but visitor surveys were not collected."},{"question_id":"9ae34067-afd1-4b66-ad4c-11ba004f6b05","answer":"To present two explanations for a decline.","accepted":"To present two explanations for a decline.","explanation":"","evidence":"One explanation for the bird’s decline is that a common insect became harder to find. A second explanation is that suitable nesting sites disappeared."},{"question_id":"dcb9ff20-0fdb-437d-95cb-f1eaa47f04ce","answer":"Repeated bending damaged the material.","accepted":"Repeated bending damaged the material.","explanation":"","evidence":"The new material conducted heat well but cracked after repeated bending. The team recommended it for rigid components."},{"question_id":"a244abb8-d165-4b00-b436-d38fffb668a6","answer":"Construction was underway before the opening.","accepted":"Construction was underway before the opening.","explanation":"","evidence":"Records indicate the building opened in 1890. A photograph dated 1888 shows workers assembling its roof."},{"question_id":"c329d3ab-e56f-41b1-a033-9eac8907d45a","answer":"6","accepted":"6","explanation":"","evidence":"3x = 18."},{"question_id":"09aae591-5b48-428e-bdec-e9aa68ca4a4d","answer":"32","accepted":"32","explanation":"","evidence":"Multiply the original price by 0.8."},{"question_id":"3ab04ebd-1861-41d6-a882-aff408a83e74","answer":"[\"5\"]","accepted":["5"],"explanation":"","evidence":"Take the positive square root."},{"question_id":"d1fddac4-a31b-4547-a72b-3851348320e0","answer":"3","accepted":"3","explanation":"","evidence":"The rise is 12 and the run is 4."},{"question_id":"a19b18e5-6f86-4f41-a5b1-8081ea269233","answer":"77","accepted":"77","explanation":"","evidence":"Multiply length by width."},{"question_id":"34f9c731-42b5-48e3-ae8c-8e2bbc5d876e","answer":"14","accepted":"14","explanation":"","evidence":"The sum divided by four is the mean."},{"question_id":"3d6b2853-17ee-4052-9ac4-db814c773d8d","answer":"25","accepted":"25","explanation":"","evidence":"One quarter of the marbles are red."},{"question_id":"82517290-9212-41d0-b943-ea7ce9b18dae","answer":"[\"8\"]","accepted":["8"],"explanation":"","evidence":"Substitute 3 for x to get 18 minus the constant."},{"question_id":"8ebd2619-9ce2-40e6-8a3c-144a0b21e428","answer":"297","accepted":"297","explanation":"","evidence":"Multiply the starting count by 3³."},{"question_id":"527eb0cf-5802-4074-b032-ccb4ff792866","answer":"60","accepted":"60","explanation":"","evidence":"The legs have a 3:4 ratio, giving a 3:4:5 triangle."},{"question_id":"1287a92e-aa72-49ba-9687-5892bb10816f","answer":"26","accepted":"26","explanation":"","evidence":"Adding the equations gives 3x = six times the common factor."},{"question_id":"d027bbc7-a89f-4907-a16f-0d5c0513c74b","answer":"28","accepted":"28","explanation":"","evidence":"3x = 84."},{"question_id":"e8cb9448-b988-4c2f-b3ad-0c95fad78231","answer":"[\"120\"]","accepted":["120"],"explanation":"","evidence":"Multiply the original price by 0.8."},{"question_id":"7c5e3954-5812-4bcf-9330-a6e5893a7457","answer":"16","accepted":"16","explanation":"","evidence":"Take the positive square root."},{"question_id":"57fade4e-e63a-44e7-8df7-13f72dc8ba80","answer":"3","accepted":"3","explanation":"","evidence":"The rise is 12 and the run is 4."},{"question_id":"fa73ad75-f6cc-4075-a7eb-7c187a0fba71","answer":"396","accepted":"396","explanation":"","evidence":"Multiply length by width."},{"question_id":"106cce8b-4b56-4dd3-b0ad-22dec72a6987","answer":"25","accepted":"25","explanation":"","evidence":"The sum divided by four is the mean."},{"question_id":"4abb3ec1-5606-4d8c-87e2-753d82872be1","answer":"[\"25\"]","accepted":["25"],"explanation":"","evidence":"One quarter of the marbles are red."},{"question_id":"1d0906ac-962d-4ce9-87f6-a88d55f8d4d5","answer":"-3","accepted":"-3","explanation":"","evidence":"Substitute 3 for x to get 18 minus the constant."},{"question_id":"7e2e6ce8-b6f7-41c2-af5e-10176ae0d3eb","answer":"594","accepted":"594","explanation":"","evidence":"Multiply the starting count by 3³."},{"question_id":"88fd5279-9185-4e06-a201-8d437d94b4a9","answer":"115","accepted":"115","explanation":"","evidence":"The legs have a 3:4 ratio, giving a 3:4:5 triangle."},{"question_id":"a2f4542a-85c5-4b7b-88af-fb54e1f6232e","answer":"[\"48\"]","accepted":["48"],"explanation":"","evidence":"Adding the equations gives 3x = six times the common factor."},{"question_id":"30a51227-1919-4880-ae79-47955e9a4699","answer":"People with little experience using tools","accepted":"People with little experience using tools","explanation":"The first paragraph says many new users had never used a drill or repaired a bicycle.","evidence":""},{"question_id":"fc39c218-4ea4-4f95-ba1e-1a7e82e514c1","answer":"To help beginners use tools","accepted":"To help beginners use tools","explanation":"The demonstrations were introduced to help people get started.","evidence":""},{"question_id":"cba2e255-daf3-4c96-a161-b97ba4c6be45","answer":"Three days","accepted":"Three days","explanation":"The first paragraph gives a three-day reservation period.","evidence":""},{"question_id":"07934897-773a-4514-9c5e-aa9330664d5b","answer":"Some items could not be stored or checked safely","accepted":"Some items could not be stored or checked safely","explanation":"Some items were too heavy or lacked safety instructions.","evidence":""},{"question_id":"9e5d55cd-699b-4312-888c-d0c4bf61fa12","answer":"To tell staff about parts that were missing","accepted":"To tell staff about parts that were missing","explanation":"The checklist let borrowers report missing parts.","evidence":""},{"question_id":"71875988-ae0b-4c95-a988-d6d141d56395","answer":"Whether tools were ready to be borrowed again","accepted":"Whether tools were ready to be borrowed again","explanation":"The service also measured how often equipment was returned ready for its next borrower.","evidence":""},{"question_id":"61ee2266-a95d-4b2a-94bb-b29ca112c771","answer":"People spent more time on the improved street","accepted":"People spent more time on the improved street","explanation":"The first paragraph reports longer stays on the improved street on warm afternoons.","evidence":""},{"question_id":"45f6d1ec-78c4-4c96-8470-9cac6499d556","answer":"Shade and seating were added to the same street","accepted":"Shade and seating were added to the same street","explanation":"The design could not isolate the effect of shade from the effect of having somewhere to sit.","evidence":""},{"question_id":"4183d4e3-2795-4bd7-81cf-23baf37053b8","answer":"Install shade and seats separately","accepted":"Install shade and seats separately","explanation":"The report proposes installing shade and seating independently across sites.","evidence":""},{"question_id":"fc75d469-45d3-4af9-a381-87c95fd01796","answer":"The original summer was relatively mild","accepted":"The original summer was relatively mild","explanation":"The researchers recommended observations in very hot weather because their first summer was mild.","evidence":""},{"question_id":"27e0ac91-ff8b-49dc-a427-fdac543ebfe0","answer":"A useful project can succeed before its causes are clear","accepted":"A useful project can succeed before its causes are clear","explanation":"The last paragraph treats usefulness and knowledge of the exact reason as different questions.","evidence":""},{"question_id":"38f425f0-a7b3-43aa-8fdb-db3fb14e393f","answer":"Which combination to use where space is limited","accepted":"Which combination to use where space is limited","explanation":"The last sentence links clearer evidence to choosing a combination of improvements on streets with less space.","evidence":""}]$catalog_json$::jsonb)
